import java.util.*;

class Solution {
    private Map<Integer, Integer> inorderMap;
    private int preIdx = 0;

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        inorderMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderMap.put(inorder[i], i);
        }
        return build(preorder, 0, inorder.length - 1);
    }

    private TreeNode build(int[] preorder, int inLeft, int inRight) {
        if (inLeft > inRight) return null;

        int rootVal = preorder[preIdx++];
        TreeNode root = new TreeNode(rootVal);

        int inIdx = inorderMap.get(rootVal);

        root.left = build(preorder, inLeft, inIdx - 1);
        root.right = build(preorder, inIdx + 1, inRight);

        return root;
    }
}

class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        return build(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1);
    }

    private TreeNode build(int[] preorder, int preStart, int preEnd, int[] inorder, int inStart, int inEnd) {
        if (preStart > preEnd || inStart > inEnd) return null;

        int rootVal = preorder[preStart];
        TreeNode root = new TreeNode(rootVal);

        int inIdx = inStart;
        while (inorder[inIdx] != rootVal) {
            inIdx++;
        }

        int leftSize = inIdx - inStart;

        root.left = build(preorder, preStart + 1, preStart + leftSize, inorder, inStart, inIdx - 1);
        root.right = build(preorder, preStart + leftSize + 1, preEnd, inorder, inIdx + 1, inEnd);

        return root;
    }
}
